/// <summary>
/// Concrete class for calculating MDF based on Invoice Amount
/// </summary>
public class METCustomerMDFCalculationRecord_InvoiceAmount extends METCustomerMDFCalculationRecord
{
}

Method.Source:
/// <summary>
/// Get amount for the given WMSOrderTrans
/// </summary>
/// <param name = "_wMSOrderTrans">WMSOrderTrans</param>
/// <returns>Amount</returns>
Amount calcAmount(WMSOrderTrans _wMSOrderTrans)
{
    return this.getInvoiceAmount(_wMSOrderTrans);
}

/// <summary>
/// Get invoice amount for the given WMSOrderTrans
/// </summary>
/// <param name = "_wMSOrderTrans">WMSOrderTrans</param>
/// <returns>Amount</returns>
private Amount getInvoiceAmount(WMSOrderTrans _wMSOrderTrans)
{
    SalesLine salesLine;
    Amount ret;

    salesLine = SalesLine::findInventTransId(_wMSOrderTrans.inventTransId);

    if (customerMDFSetupTable.IncludeTaxesInThreshold)
    {
        ret = salesLine.LineAmount;
    }
    else
    {
        ret = salesLine.lineAmountExclTax();
    }

    // Adjust amount if original qty is different than current qty (e.g., partial shipment)
    METWMSOrderTrans wMSOrderTrans = METWMSOrderTrans::find(_wMSOrderTrans.RecId);
    if(wMSOrderTrans.qtyOrig != _wMSOrderTrans.qty && wMSOrderTrans.qtyOrig && ret)
    {
        ret = (ret / wMSOrderTrans.qtyOrig) * _wMSOrderTrans.qty;
    }

    return ret;
}
